+        Mate { part: stock_face(world, [0.0, -1.0, 0.0]), fixture: vise_face(world, [50.0, -1.0, 20.25]) },
+        Mate { part: stock_face(world, [-1.0, 0.0, 0.0]), fixture: vise_face(world, [-1.0, 30.0, 15.25]) },
